using System;
using System.Collections.Generic;
using Aspose.Cells;

// The example creates a workbook, defines smart markers for product data, embeds a formula in the Total column that multiplies Quantity and Price for each generated row, processes the markers with a List<Product> data source, recalculates all formulas, and saves the result as an .xlsx file.
class SmartMarkerFormulaDemo
{
    static void Main()
    {
        // Create a new workbook and get the first worksheet
        Workbook wb = new Workbook();
        Worksheet ws = wb.Worksheets[0];
        Cells cells = ws.Cells;

        // Header row
        cells["A1"].PutValue("Name");
        cells["B1"].PutValue("Quantity");
        cells["C1"].PutValue("Price");
        cells["D1"].PutValue("Total"); // This column will contain a formula

        // Smart markers for data rows (starting at row 2)
        cells["A2"].PutValue("&=Products.Name");
        cells["B2"].PutValue("&=Products.Quantity");
        cells["C2"].PutValue("&=Products.Price");

        // Embed a formula that references the Quantity (B) and Price (C) cells of the same row.
        // The second parameter is a placeholder value; it will be recalculated after processing.
        cells["D2"].SetFormula("=B2*C2", 0);

        // Sample data source
        var products = new List<Product>
        {
            new Product { Name = "Apple",  Quantity = 10, Price = 0.5 },
            new Product { Name = "Banana", Quantity = 5,  Price = 0.3 },
            new Product { Name = "Cherry", Quantity = 20, Price = 0.2 }
        };

        // Configure the WorkbookDesigner with the data source
        WorkbookDesigner designer = new WorkbookDesigner(wb);
        designer.SetDataSource("Products", products);

        // Process smart markers (true = preserve unrecognized markers)
        designer.Process(true);

        // Calculate all formulas now that the data has been populated
        wb.CalculateFormula();

        // Save the resulting workbook
        wb.Save("SmartMarkerWithFormula.xlsx");
    }

    // Simple POCO class used as the data source
    public class Product
    {
        public string Name { get; set; }
        public int Quantity { get; set; }
        public double Price { get; set; }
    }
}
